class Solution { public: double champagneTower(int poured,int query_row,int query_glass){vector<double> amount(query_row+2);amount[0]=poured;for(int row=0;row<query_row;++row)for(int glass=row;glass>=0;--glass){double overflow=max(0.0,(amount[glass]-1.0)/2.0);amount[glass]=overflow;amount[glass+1]+=overflow;}return min(1.0,amount[query_glass]);} };
